let rsa_n = ""
let rsa_message = "I am the message a certificate would be."
let rsa_pkcs1_256 = ""
let rsa_pkcs1_384 = ""
let rsa_pss_256 = ""

let flip (s : string) (i : int) : string = String.mapi (fun j c -> if j = i then Char.chr (Char.code c lxor 1) else c) s
let big = Bignum.of_hex

let tests =
  Testo.categorize "Public key"
    [
      Testo.create "Bignum: bytes, products, remainders, powers (Python's)" (fun () ->
          let p = Bignum.sub (Bignum.shift_left Bignum.one 255) (Bignum.of_int 19) in
          check_hex "2^255-19" "7fffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffed" (Bignum.to_bytes ~len:32 p);
          Alcotest.(check bool) "and back" true (Bignum.equal p (Bignum.of_bytes (Bignum.to_bytes ~len:32 p)));
          List.iter
            (fun (a, b, m, ab, amodm, pow) ->
              Alcotest.(check string) "a*b" ab (Bignum.to_hex (Bignum.mul (big a) (big b)));
              Alcotest.(check string) "a mod m" amodm (Bignum.to_hex (Bignum.rem (big a) (big m)));
              Alcotest.(check string) "a^b mod m" pow (Bignum.to_hex (Bignum.pow_mod (Bignum.modulus (big m)) (big a) (big b)));
              Alcotest.(check string) "(a*b - b) + b" ab (Bignum.to_hex (Bignum.add (Bignum.sub (Bignum.mul (big a) (big b)) (big b)) (big b))))
            arith;
          let md = Bignum.modulus (big "ffffffff00000001000000000000000000000000ffffffffffffffffffffffff") in
          Alcotest.(check string) "7 * 1/7" "1" (Bignum.to_hex (Bignum.mul_mod md (Bignum.of_int 7) (Bignum.inverse_prime md (Bignum.of_int 7)))));
      Testo.create "X25519: RFC 7748's vectors (5.2) and Alice and Bob (6.1)" (fun () ->
          check_hex "1" "c3da55379de9c6908e94ea4df28d084f32eccf03491c71f754b4075577a28552"
            (X25519.scalar_mult (unhex "a546e36bf0527c9d3b16154b82465edd62144c0ac1fc5a18506a2244ba449ac4")
               (unhex "e6db6867583030db3594c1a424b15f7c726624ec26b3353b10a903a6d0ab1c4c"));
          check_hex "2" "95cbde9476e8907d7aade45cb4b873f88b595a68799fa152e6f8f7647aac7957"
            (X25519.scalar_mult (unhex "4b66e9d4d1b4673c5ad22691957d6af5c11b6421e0ea01d42ca4169e7918ba0d")
               (unhex "e5210f12786811d3f4b7959d0538ae2c31dbe7106fc03c3efc4cd549c715a493"));
          let a = unhex "77076d0a7318a57d3c16c17251b26645df4c2f87ebc0992ab177fba51db92c2a" in
          let b = unhex "5dab087e624a8a4b79e17f8b83800ee66f3bb1292618b6fd1c2f8b27ff88e0eb" in
          check_hex "Alice's public key" "8520f0098930a754748b7ddcb43ef75a0dbf3a0d26381af4eba4a98eaa9b4e6a" (X25519.public_key a);
          check_hex "Bob's public key" "de9edb7d7b7dc1b4d35b61c2ece435373f8343c85b78674dadfc7e146f882b4f" (X25519.public_key b);
          let k = "4a5d9d5ba4ce2de1728e3bf480350f25e07e21c947d19e3376f09b3c1e161742" in
          check_hex "Alice's secret" k (X25519.scalar_mult a (X25519.public_key b));
          check_hex "Bob's secret, the same" k (X25519.scalar_mult b (X25519.public_key a)));
      Testo.create "the curves' constants: G on the curve, n*G = O" (fun () ->
          Alcotest.(check bool) "P-256" true (Ecdsa.generator_ok Ecdsa.p256);
          Alcotest.(check bool) "P-384" true (Ecdsa.generator_ok Ecdsa.p384));
      Testo.create "ECDSA: Python's signatures, and changed ones" (fun () ->
          let check curve digest cases =
            List.iteri
              (fun i (public, message, r, s) ->
                let ok m r = Ecdsa.verify curve ~public:(unhex public) ~hash:(digest (unhex m)) ~r ~s:(big s) in
                Alcotest.(check bool) (Printf.sprintf "%d accepted" i) true (ok message (big r));
                Alcotest.(check bool) (Printf.sprintf "%d, message changed" i) false (ok (hex (flip (unhex message) 0)) (big r));
                Alcotest.(check bool) (Printf.sprintf "%d, r changed" i) false (ok message (Bignum.add (big r) Bignum.one)))
              cases
          in
          check Ecdsa.p256 Sha256.digest p256;
          check Ecdsa.p384 Sha512.digest384 p384);
      Testo.create "RSA: PKCS#1 v1.5 and PSS, Python's" (fun () ->
          let n = big rsa_n and e = Bignum.of_int 65537 in
          let v1 h s = Rsa.verify_pkcs1 ~n ~e h ~message:rsa_message ~signature:(unhex s) in
          Alcotest.(check bool) "v1.5, SHA-256" true (v1 Rsa.Sha256 rsa_pkcs1_256);
          Alcotest.(check bool) "v1.5, SHA-384" true (v1 Rsa.Sha384 rsa_pkcs1_384);
          Alcotest.(check bool) "v1.5, the wrong hash" false (v1 Rsa.Sha384 rsa_pkcs1_256);
          Alcotest.(check bool) "v1.5, a byte changed" false (v1 Rsa.Sha256 (hex (flip (unhex rsa_pkcs1_256) 100)));
          let pss m s = Rsa.verify_pss ~n ~e Rsa.Sha256 ~message:m ~signature:(unhex s) in
          Alcotest.(check bool) "PSS" true (pss rsa_message rsa_pss_256);
          Alcotest.(check bool) "PSS, message changed" false (pss (rsa_message ^ ".") rsa_pss_256);
          Alcotest.(check bool) "PSS is not v1.5" false (v1 Rsa.Sha256 rsa_pss_256));
    ]
